def table(df):
    return '<div class="scroll">'+df.to_html(index=False,border=0,na_rep='—',float_format=lambda v:f'{v:,.2f}',escape=True)+'</div>'
def img(path):return '<img alt="Research results chart" src="data:image/png;base64,'+base64.b64encode(path.read_bytes()).decode()+'">'

