for arm,color,label in [('S01','#175b9a','Bounded evidence: candidate'),('S00','#878c96','Unbounded evidence: control')]:
    q=d[(d.arm==arm)&(d.cost=='desk')&(d.delay==1)].sort_values('day');axes[1].plot(pd.Timestamp('2022-01-01')+pd.to_timedelta(q.day,unit='D'),q.net.cumsum()/1000,color=color,label=label,lw=1.3)
axes[1].axhline(0,color='#444',lw=.7);axes[1].set_title('Marked opportunity P&L · NOT funded equity');axes[1].set_ylabel('Thousands of USDT');axes[1].legend(fontsize=8)
