parts+=['<p>S00 is the unbounded control. Its later entry cohorts are slightly profitable, but its full-period and later calendar P&L are negative. It cannot be relabelled a successful strategy by choosing the most flattering window. Both candidates remain research rejections.</p>','<details><summary>Severe cost sensitivity — secondary</summary>']
parts.append(table(s[(s.delay==1)&(s.cost=='severe')][['arm','cost']+cols].rename(columns=rename)));parts.append('</details>')
